import "./Admin.css";
import { useEffect, useState, useCallback } from "react";

function Admin() {
  // ====== AUTH ======
  const [isAdminExists, setIsAdminExists] = useState(true);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [otp, setOtp] = useState("");
  const [loginStep, setLoginStep] = useState("password"); // "password" | "otp"

  const [token, setToken] = useState(localStorage.getItem("token") || "");

  // ====== INQUIRIES ======
  const [inquiries, setInquiries] = useState([]);
  const [search, setSearch] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const inquiriesPerPage = 5;

  // ====== SERVICES ======
  const [services, setServices] = useState([]);
  const [serviceName, setServiceName] = useState("");
  const [documents, setDocuments] = useState("");
  const [price, setPrice] = useState("");
  const [duration, setDuration] = useState("");
  const [description, setDescription] = useState("");
  const [imageURL, setImageURL] = useState("");

  // ====== SLIDER IMAGES ======
  const [selectedFile, setSelectedFile] = useState(null);
  const [images, setImages] = useState([]);

  // ====== ACTIVE SECTION ======
  const [activeSection, setActiveSection] = useState(null); // "inquiries" | "services" | "slider" | null

  // ====== CHECK IF ADMIN EXISTS ======
  const checkAdmin = useCallback(async () => {
    try {
      const res = await fetch("http://127.0.0.1:8000/check-admin");
      const data = await res.json();
      setIsAdminExists(data.exists);
    } catch (err) {
      console.error("Error checking admin:", err);
    }
  }, []);

  // ====== FIRST-TIME ADMIN REGISTRATION ======
  const registerAdmin = async () => {
    if (!username || !password) return alert("Enter username and password");
    try {
      const res = await fetch("http://127.0.0.1:8000/register-admin", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ username, password }),
      });
      const data = await res.json();
      if (res.ok) {
        alert("Admin registered successfully! Please login.");
        setIsAdminExists(true);
        setUsername("");
        setPassword("");
      } else {
        alert(data.detail);
      }
    } catch (err) {
      console.error("Error registering admin:", err);
    }
  };

  // ====== ADMIN LOGIN ======
  const login = async () => {
    if (!username || !password) return alert("Enter username and password");
    try {
      const formData = new URLSearchParams();
      formData.append("username", username);
      formData.append("password", password);

      const res = await fetch("http://127.0.0.1:8000/login", {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body: formData,
      });
      const data = await res.json();
      if (res.ok) {
        localStorage.setItem("token", data.access_token);
        setToken(data.access_token);
        setIsLoggedIn(true);
      } else {
        alert(data.detail);
      }
    } catch (err) {
      console.error("Login error:", err);
    }
  };

  // ====== OTP LOGIN ======
  const requestOtp = async () => {
    if (!username) return alert("Enter username");
    try {
      const res = await fetch(`http://127.0.0.1:8000/request-otp?username=${username}`, {
        method: "POST",
      });
      const data = await res.json();
      if (res.ok) {
        alert(`OTP sent: ${data.otp}`);
        setLoginStep("otp");
      } else {
        alert(data.detail);
      }
    } catch (err) {
      console.error("OTP request error:", err);
    }
  };

  const loginOtp = async () => {
    if (!otp) return alert("Enter OTP");
    try {
      const res = await fetch(`http://127.0.0.1:8000/login-otp?username=${username}&otp=${otp}`, {
        method: "POST",
      });
      const data = await res.json();
      if (res.ok) {
        localStorage.setItem("token", data.access_token);
        setToken(data.access_token);
        setIsLoggedIn(true);
      } else {
        alert(data.detail);
      }
    } catch (err) {
      console.error("OTP login error:", err);
    }
  };

  const logout = () => {
    localStorage.removeItem("token");
    setToken("");
    setIsLoggedIn(false);
  };

  // ====== FETCH INQUIRIES ======
  const fetchInquiries = useCallback(async () => {
    try {
      const res = await fetch("http://127.0.0.1:8000/inquiries", {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await res.json();
      setInquiries(data);
    } catch (err) {
      console.error("Error fetching inquiries:", err);
    }
  }, [token]);

  const deleteInquiry = async (id) => {
    if (!window.confirm("Delete this inquiry?")) return;
    try {
      const res = await fetch(`http://127.0.0.1:8000/inquiry/${id}`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${token}` },
      });
      if (res.ok) {
        alert("Inquiry deleted successfully!");
        fetchInquiries();
      } else {
        const data = await res.json();
        alert(data.detail);
      }
    } catch (err) {
      console.error("Error deleting inquiry:", err);
    }
  };

  // ====== FETCH SERVICES ======
  const fetchServices = useCallback(async () => {
    try {
      const res = await fetch("http://127.0.0.1:8000/services", {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await res.json();
      setServices(data);
    } catch (err) {
      console.error("Error fetching services:", err);
    }
  }, [token]);

  const addService = async () => {
    if (!serviceName || !documents || !price || !duration || !description)
      return alert("Fill all fields");

    try {
      const res = await fetch("http://127.0.0.1:8000/service", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ serviceName, documents, price, duration, description, imageURL }),
      });
      if (res.ok) {
        alert("Service added successfully!");
        fetchServices();
        setServiceName("");
        setDocuments("");
        setPrice("");
        setDuration("");
        setDescription("");
        setImageURL("");
      }
    } catch (err) {
      console.error("Error adding service:", err);
    }
  };

  const deleteService = async (id) => {
    if (!window.confirm("Delete this service?")) return;
    try {
      const res = await fetch(`http://127.0.0.1:8000/service/${id}`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${token}` },
      });
      if (res.ok) {
        alert("Service deleted successfully!");
        fetchServices();
      }
    } catch (err) {
      console.error("Error deleting service:", err);
    }
  };

  // ====== SLIDER IMAGES ======
  const fetchImages = useCallback(async () => {
    try {
      const res = await fetch("http://127.0.0.1:8000/images", {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await res.json();
      setImages(data.images || []);
    } catch (err) {
      console.error("Error fetching images:", err);
    }
  }, [token]);

  const handleUpload = async () => {
    if (!selectedFile) return alert("Select a file");
    const formData = new FormData();
    formData.append("file", selectedFile);
    try {
      await fetch("http://127.0.0.1:8000/upload-image", {
        method: "POST",
        headers: { Authorization: `Bearer ${token}` },
        body: formData,
      });
      alert("Image uploaded!");
      fetchImages();
    } catch (err) {
      console.error("Error uploading image:", err);
    }
  };

  const handleDeleteImage = async (fileName) => {
    if (!window.confirm("Delete this image?")) return;
    try {
      await fetch(`http://127.0.0.1:8000/delete-image/${fileName}`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${token}` },
      });
      alert("Image deleted!");
      fetchImages();
    } catch (err) {
      console.error("Error deleting image:", err);
    }
  };

  // ====== PAGINATION ======
  const indexOfLastInquiry = currentPage * inquiriesPerPage;
  const indexOfFirstInquiry = indexOfLastInquiry - inquiriesPerPage;
  const filteredInquiries = inquiries
    .filter(
      (inq) =>
        inq.name.toLowerCase().includes(search.toLowerCase()) ||
        inq.mobile.includes(search)
    )
    .sort((a, b) => new Date(b.date) - new Date(a.date));
  const currentInquiries = filteredInquiries.slice(indexOfFirstInquiry, indexOfLastInquiry);
  const totalPages = Math.ceil(filteredInquiries.length / inquiriesPerPage);

  const handleNext = () => currentPage < totalPages && setCurrentPage(currentPage + 1);
  const handlePrev = () => currentPage > 1 && setCurrentPage(currentPage - 1);

  // ====== EFFECTS ======
  useEffect(() => {
    checkAdmin();
  }, [checkAdmin]);

  useEffect(() => {
    if (!isLoggedIn) return;
    if (activeSection === "inquiries") fetchInquiries();
    if (activeSection === "services") fetchServices();
    if (activeSection === "slider") fetchImages();
  }, [activeSection, fetchInquiries, fetchServices, fetchImages, isLoggedIn]);

  // ====== RENDER ======
  if (!isAdminExists) {
    return (
      <div className="admin-container">
        <h2>Register First Admin</h2>
        <input value={username} placeholder="Username" onChange={(e) => setUsername(e.target.value)} />
        <input type="password" value={password} placeholder="Password" onChange={(e) => setPassword(e.target.value)} />
        <button onClick={registerAdmin}>Register</button>
      </div>
    );
  }

  if (!isLoggedIn) {
    return (
      <div className="admin-container">
        <h2>Admin Login</h2>
        <input value={username} placeholder="Username" onChange={(e) => setUsername(e.target.value)} />
        {loginStep === "password" && (
          <>
            <input type="password" value={password} placeholder="Password" onChange={(e) => setPassword(e.target.value)} />
            <button onClick={login}>Login</button>
            <button onClick={requestOtp}>Login via OTP</button>
          </>
        )}
        {loginStep === "otp" && (
          <>
            <input value={otp} placeholder="Enter OTP" onChange={(e) => setOtp(e.target.value)} />
            <button onClick={loginOtp}>Login OTP</button>
          </>
        )}
      </div>
    );
  }

  return (
    <div className="admin-container">
      <h1>Admin Dashboard</h1>
      <button onClick={logout} style={{ marginBottom: "15px" }}>Logout</button>

      {!activeSection && (
        <div className="admin-menu">
          <button onClick={() => setActiveSection("inquiries")}>📋 Manage Inquiries</button>
          <button onClick={() => setActiveSection("services")}>🛠 Manage Services</button>
          <button onClick={() => setActiveSection("slider")}>🖼 Manage Slider Images</button>
        </div>
      )}

      {/* ===== INQUIRIES SECTION ===== */}
      {activeSection === "inquiries" && (
        <div className="inquiries-section">
          <h2>Inquiries</h2>
          <button onClick={() => setActiveSection(null)}>⬅ Back</button>
          <input value={search} placeholder="Search by name or mobile" onChange={(e) => setSearch(e.target.value)} />
          {currentInquiries.length === 0 ? <p>No inquiries found.</p> :
            <>
              <table border="1" cellPadding="10">
                <thead>
                  <tr>
                    <th>Name</th><th>Email</th><th>Mobile</th><th>Message</th><th>Date</th><th>Action</th>
                  </tr>
                </thead>
                <tbody>
                  {currentInquiries.map((inq) => (
                    <tr key={inq._id}>
                      <td>{inq.name}</td><td>{inq.email}</td><td>{inq.mobile}</td>
                      <td>{inq.message}</td>
                      <td>{new Date(inq.date).toLocaleString()}</td>
                      <td><button onClick={() => deleteInquiry(inq._id)}>Delete</button></td>
                    </tr>
                  ))}
                </tbody>
              </table>
              <div>
                <button onClick={handlePrev} disabled={currentPage === 1}>Previous</button>
                <button onClick={handleNext} disabled={currentPage === totalPages}>Next</button>
              </div>
            </>
          }
        </div>
      )}

      {/* ===== SERVICES SECTION ===== */}
      {activeSection === "services" && (
        <div className="services-section">
          <h2>Manage Services</h2>
          <button onClick={() => setActiveSection(null)}>⬅ Back</button>
          <div>
            <input placeholder="Service Name" value={serviceName} onChange={(e) => setServiceName(e.target.value)} />
            <input placeholder="Documents" value={documents} onChange={(e) => setDocuments(e.target.value)} />
            <input placeholder="Price" value={price} onChange={(e) => setPrice(e.target.value)} />
            <input placeholder="Duration" value={duration} onChange={(e) => setDuration(e.target.value)} />
            <input placeholder="Description" value={description} onChange={(e) => setDescription(e.target.value)} />
            <input placeholder="Image URL" value={imageURL} onChange={(e) => setImageURL(e.target.value)} />
            <button onClick={addService}>Add Service</button>
          </div>
          {services.length > 0 && (
            <table border="1" cellPadding="10">
              <thead>
                <tr>
                  <th>Name</th><th>Docs</th><th>Price</th><th>Duration</th><th>Description</th><th>Image</th><th>Action</th>
                </tr>
              </thead>
              <tbody>
                {services.map((s) => (
                  <tr key={s._id}>
                    <td>{s.serviceName}</td><td>{s.documents}</td><td>{s.price}</td><td>{s.duration}</td>
                    <td>{s.description}</td>
                    <td>{s.imageURL && <img src={s.imageURL} alt={s.serviceName} width="50" />}</td>
                    <td><button onClick={() => deleteService(s._id)}>Delete</button></td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      )}

      {/* ===== SLIDER IMAGES SECTION ===== */}
      {activeSection === "slider" && (
        <div className="slider-section">
          <h2>Manage Slider Images</h2>
          <button onClick={() => setActiveSection(null)}>⬅ Back</button>
          <input type="file" accept="image/*" onChange={(e) => setSelectedFile(e.target.files[0])} />
          <button onClick={handleUpload}>Upload</button>
          <div style={{ display: "flex", flexWrap: "wrap", gap: "10px" }}>
            {images.map((url, index) => {
              const fileName = url.split("/").pop();
              return (
                <div key={index} style={{ position: "relative" }}>
                  <img src={url} alt={`slide-${index}`} width="150" style={{ borderRadius: "8px", border: "1px solid #ccc" }} />
                  <button onClick={() => handleDeleteImage(fileName)} style={{ position: "absolute", top: "5px", right: "5px", background: "red", color: "white", border: "none", padding: "4px 6px", cursor: "pointer", borderRadius: "4px" }}>X</button>
                </div>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}

export default Admin;
